(function(E){ const x = E["mkt-m3"] = E["mkt-m3"] || {units:{}}; x.units["mkt-9"] = {"grammar":{"id":"c-mkt-9-g","level":"B1","course":"marketing","unit":"mkt-9","title":"An exact apology: sorry that, sorry for, apologise for","titleTr":"Net bir özür: sorry that, sorry for, apologise for","titleFa":"عذرخواهی دقیق: sorry that، sorry for، apologise for","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["sorry that + full sentence","We're sorry that our towel damaged your shirts."],["sorry for + -ing","We're sorry for damaging your shirts."],["sorry for + noun","We're sorry for the trouble."],["apologise to + person + for + noun / -ing","We apologise to the customer for the mistake."]]},"wrong":"We're sorry for damage your shirts.","right":"We're sorry for damaging your shirts.","blank":{"sentence":"We're sorry ___ our label gave the wrong temperature.","word":"that","distractors":["for","to"]},"wrong2":"We apologise to the wrong label.","right2":"We apologise for the wrong label.","blank2":{"sentence":"We apologise ___ the wrong care label.","word":"for","distractors":["to","of"]},"expParts":{"tryFrom":"blank","rule":[{"en":"sorry that + a full sentence.","tr":"sorry that + tam bir cümle.","fa":"بعد از sorry that یک جمله‌ی کامل می‌آید.","ex":"We're sorry that our label was wrong."},{"en":"sorry for + -ing or a noun.","tr":"sorry for + -ing ya da bir isim.","fa":"بعد از sorry for فعل -ing‌دار یا یک اسم می‌آید.","ex":"sorry for damaging your shirts"},{"en":"apologise for the thing, to the person.","tr":"Olan şey için for, kişi için to.","fa":"بعد از apologise، برای آن اتفاق for می‌آید و برای آن شخص to.","ex":"We apologise to the customer for the mistake."},{"en":"Then say what you have done.","tr":"Sonra ne yaptığını söyle.","fa":"بعد بگو چه کرده‌ای.","ex":"We've changed the label."}],"test":{"en":"After for, check: is there -ing or a noun? After that, check: is there a subject and a verb?","tr":"for'dan sonra kontrol et: -ing ya da bir isim var mı? that'ten sonra kontrol et: özne ve fiil var mı?","fa":"بعد از for بررسی کن: ‎-ing یا اسم آمده؟ بعد از that بررسی کن: فاعل و فعل آمده؟"},"contrast":{"en":"Turkish says \"zarar verdiğimiz için özür dileriz\" and Persian «بابت آسیبی که زدیم عذر می‌خواهیم»: one form carries the reason. English needs for + -ing or that + a full sentence, so learners write \"sorry for damage\".","tr":"Türkçede \"zarar verdiğimiz için özür dileriz\" deriz; sebep tek bir yapının içindedir. İngilizcede for + -ing ya da that + tam cümle gerekir; bu yüzden \"sorry for damage\" yazılır.","fa":"در فارسی می‌گوییم «بابت آسیبی که زدیم عذر می‌خواهیم» و دلیل در یک ساختار می‌آید. انگلیسی for با -ing یا that با جمله‌ی کامل لازم دارد؛ برای همین می‌نویسیم «sorry for damage»."}},"errorWatch":[{"find":["sorry for damage your","sorry for ruin","sorry for send","sorry for give","apologise to the mistake","apologise to the wrong","apologize to the mistake","sorry about to"],"fix":{"en":"Say sorry for + -ing (\"sorry for damaging\"), or sorry that + a full sentence. Apologise for the thing, to the person.","tr":"sorry for + -ing (\"sorry for damaging\") ya da sorry that + tam cümle kullan. Olan şey için apologise for, kişi için apologise to.","fa":"بگو sorry for با -ing («sorry for damaging») یا sorry that با جمله‌ی کامل. برای اتفاق apologise for و برای شخص apologise to."}}]},"b2":{"id":"c-mkt-9-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-9","title":"Owning a past mistake: should have, shouldn't have","titleTr":"Geçmişteki bir hatayı üstlenmek: should have, shouldn't have","titleFa":"پذیرفتن اشتباه گذشته: should have، shouldn't have","formsTable":{"headers":{"en":["Form","Use","Example"],"tr":["Yapı","Kullanım","Örnek"],"fa":["ساختار","کاربرد","مثال"]},"rows":[["should have + past participle","the right thing did not happen","Our label should have said 30°C."],["shouldn't have + past participle","the wrong thing happened","We shouldn't have used one label for every colour."]]},"wrong":"Our label should had said 30°C.","right":"Our label should have said 30°C.","blank":{"sentence":"We should have ___ the navy batch separately.","word":"tested","distractors":["test","testing"]},"wrong2":"We shouldn't have use one label for every colour.","right2":"We shouldn't have used one label for every colour.","blank2":{"sentence":"Our label should ___ said 30°C, not 60°C.","word":"have","distractors":["had","has"]},"useIn":{"en":"B2: in your public reply, own the mistake with should have or shouldn't have + past participle.","tr":"B2: herkese açık yanıtında hatayı should have ya da shouldn't have + üçüncü hâl ile üstlen.","fa":"B2: در جواب عمومی‌ات اشتباه را با should have یا shouldn't have و اسم مفعول بپذیر."},"exitItem":{"from":"mkt-9","kind":"blank","prompt":"We should have ___ the customer sooner.","options":["called","call","calling"],"correct":0},"expParts":{"tryFrom":"blank","rule":[{"en":"Right thing that did not happen: should have + past participle.","tr":"Olması gerekip olmayan şey: should have + üçüncü hâl.","fa":"should have با اسم مفعول همان «باید ... می‌کردیم» فارسی است: کاری که باید انجام می‌دادی و ندادی.","ex":"The label should have said 30°C."},{"en":"Wrong thing that happened: shouldn't have + past participle.","tr":"Olmaması gerekip olan şey: shouldn't have + üçüncü hâl.","fa":"shouldn't have با اسم مفعول یعنی کاری که نباید می‌کردی و کردی.","ex":"We shouldn't have used one label."},{"en":"Say we, not you: own it.","tr":"You değil, we de: hatayı üstlen.","fa":"بگو we، نه you: اشتباه را بپذیر.","ex":"We should have checked."}],"test":{"en":"Is it about the past? After should, use have + past participle.","tr":"Geçmişle mi ilgili? Should'dan sonra have + üçüncü hâl kullan.","fa":"درباره‌ی گذشته است؟ بعد از should، have و اسم مفعول بیاور."},"contrast":{"en":"Turkish \"...yazması gerekirdi\" and Persian «باید ... می‌نوشت» put the past inside the verb. English adds have + past participle after should.","tr":"Türkçede \"...yazması gerekirdi\" derken geçmiş fiilin içindedir. İngilizce should'dan sonra have + üçüncü hâl ekler.","fa":"در فارسی «باید ... می‌نوشت» گذشته را داخل فعل می‌آورد. انگلیسی بعد از should، have و اسم مفعول اضافه می‌کند."}},"errorWatch":[{"find":["should had","should has","should have say","should of","shouldn't of","should have test the","shouldn't have use one"],"fix":{"en":"After should: have + past participle (\"should have said\", \"shouldn't have used\").","tr":"Should'dan sonra: have + üçüncü hâl (\"should have said\", \"shouldn't have used\").","fa":"بعد از should، have و اسم مفعول می‌آید («should have said»، «shouldn't have used»)."}}]},"vocab":{"id":"c-mkt-9-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-9","goals":["career"],"title":{"en":"Reviews and Replies","tr":"Yorumlar ve Yanıtlar","fa":"نظر مشتری و پاسخ"},"cards":[{"word":"review","sentence":"One honest review can bring more trust than a hundred perfect ones.","meaning":{"en":"A customer's public opinion of a product, often with stars.","tr":"müşteri yorumu","fa":"نقد؛ نظر مشتری"}},{"word":"complaint","sentence":"Every complaint goes to customer care first.","meaning":{"en":"A statement that something is wrong or not good enough.","tr":"şikâyet","fa":"شکایت"}},{"word":"respond","sentence":"We respond to every review within 24 hours.","meaning":{"en":"To answer.","tr":"yanıt vermek","fa":"پاسخ دادن"}},{"word":"publicly","sentence":"Answer publicly, so other customers can see what you did.","meaning":{"en":"In a way that everyone can see.","tr":"herkesin önünde, açıkça","fa":"به‌طور عمومی؛ جلوی همه"}},{"word":"privately","sentence":"Discuss the money privately, by email or phone.","meaning":{"en":"In a way that only the people involved can see.","tr":"özel olarak","fa":"به‌طور خصوصی"}},{"word":"refund","sentence":"The team offered a refund for the shirts.","meaning":{"en":"Money paid back to a customer.","tr":"para iadesi","fa":"بازگرداندن پول"}},{"word":"reputation","sentence":"A brand's reputation is built one reply at a time.","meaning":{"en":"What people think about a company.","tr":"itibar","fa":"شهرت؛ اعتبار"}},{"word":"take responsibility","sentence":"In the reply, we take responsibility for the wrong label.","meaning":{"en":"To say that a mistake was yours.","tr":"sorumluluğu üstlenmek","fa":"مسئولیت را پذیرفتن"}},{"word":"defensive","sentence":"A defensive reply makes an angry customer angrier.","meaning":{"en":"Trying to protect yourself instead of listening.","tr":"savunmacı","fa":"تدافعی"}},{"word":"resolve","sentence":"The team resolved the problem the same day.","gap":"resolved","accept":["resolved","resolve"],"meaning":{"en":"To solve a problem or end a complaint.","tr":"çözmek","fa":"حل کردن"}}]},"judge":{"id":"c-mkt-9-j","course":"marketing","unit":"mkt-9","type":"judge","title":{"en":"A reply in public","tr":"Herkese açık bir cevap","fa":"یک جواب عمومی"},"prompt":"A 1-star review with photos: a mug arrived broken. The shop's packing was too thin. Four possible public replies.","parts":["Says sorry clearly","Owns the mistake","Says what happens next"],"instruction":{"en":"Tap what each reply does well. The reply to post has all three.","tr":"Her cevabın iyi yaptığı şeylere dokun. Yayımlanacak cevapta üçü de vardır.","fa":"روی کارهایی که هر جواب درست انجام داده بزن. جوابی که منتشر می‌شود هر سه را دارد."},"items":[{"by":"AI tool","answer":"We apologise for any inconvenience caused. Our products are of the highest quality. Please contact customer service.","present":[],"fix":{"en":"\"Any inconvenience\" hides the problem, \"highest quality\" argues with her photos, and \"contact customer service\" gives her more work.","tr":"\"Any inconvenience\" sorunu gizliyor, \"highest quality\" fotoğraflarla tartışıyor, \"contact customer service\" de ona daha çok iş çıkarıyor.","fa":"«Any inconvenience» مشکل را پنهان می‌کند، «highest quality» با عکس‌هایش بحث می‌کند و «contact customer service» کار بیشتری گردن مشتری می‌اندازد."}},{"by":"Owner","answer":"Thank you for your feedback! Please check our delivery guide for tips.","present":[],"fix":{"en":"It suggests that the customer did something wrong. Own the mistake first.","tr":"Müşterinin bir hata yaptığını ima ediyor. Önce hatayı üstlen.","fa":"این‌طور می‌رساند که مشتری کار اشتباهی کرده. اول اشتباه را بپذیر."}},{"by":"Good model","answer":"We're very sorry that your mug arrived broken. Our packing was too thin, and we now use double boxes. We've emailed you about a replacement.","present":["Says sorry clearly","Owns the mistake","Says what happens next"],"fix":null},{"by":"AI tool","answer":"We're sorry that the packing was too thin. We have changed it for all orders.","present":["Says sorry clearly","Owns the mistake"],"fix":{"en":"Good and exact. Add the customer's next step: \"We've emailed you about a replacement.\"","tr":"İyi ve net. Müşterinin sonraki adımını ekle: \"We've emailed you about a replacement.\"","fa":"خوب و دقیق است. قدم بعدی مشتری را اضافه کن: «We've emailed you about a replacement.»"}}]},"writing":{"id":"c-mkt-9-w","title":{"en":"A public reply","tr":"Herkese açık bir cevap","fa":"یک جواب عمومی"},"course":"marketing","unit":"mkt-9","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Write a public reply (50-70 words) to a real complaint about your product, or to this review of a towel shop: \"I followed the care label: 60 degrees. The dye ruined my white shirts. So much for quality.\" Facts: the label was wrong; this dye needs 30°C; labels are now changed; a replacement and money for the shirts were emailed. Name it, own it, say what changed and what happens next.","tr":"Ürününle ilgili gerçek bir şikâyete ya da bir havlu mağazası hakkındaki şu yoruma herkese açık cevap yaz (50-70 kelime): \"I followed the care label: 60 degrees. The dye ruined my white shirts. So much for quality.\" Bilgiler: etiket yanlıştı; bu boya 30°C istiyor; etiketler değiştirildi; yeni ürün ve gömleklerin parası için e-posta gönderildi. Sorunu söyle, üstlen, neyin değiştiğini ve sonra ne olacağını yaz.","fa":"به یک شکایت واقعی درباره‌ی محصولت، یا این نظر منفی درباره‌ی یک فروشگاه حوله جواب عمومی بنویس (۵۰ تا ۷۰ کلمه): «I followed the care label: 60 degrees. The dye ruined my white shirts. So much for quality.» واقعیت‌ها: برچسب اشتباه بود؛ این رنگ ۳۰ درجه می‌خواهد؛ برچسب‌ها عوض شده؛ درباره‌ی جایگزین و پول پیراهن‌ها ایمیل فرستاده شده. مشکل را بگو، بپذیر، بگو چه چیزی عوض شده و قدم بعدی چیست."},"model":"We're very sorry that our towel damaged your shirts. You followed our care label, and our label was wrong: this dye needs 30°C, not 60°C. We've changed the label on all our dark colours. We've also emailed you about a new towel and the cost of the shirts. Thank you for telling us, and we are sorry again for the trouble.","frame":"We're very sorry that ___. You ___, and ___: ___. We've changed ___. We've also emailed you about ___. Thank you for ___.","words":[{"word":"sorry that"},{"word":"we've"},{"word":"thank you"}],"minWords":50,"minSentences":4,"rubric":["Task done: exact sorry, cause owned, what changed, next step, thanks","Organised: sorry, cause, change, next step","Language: sorry that + sentence; sorry for + -ing or noun","Tone: calm and human; no \"any inconvenience\", no blame"],"rubricI18n":{"tr":["Görev: net özür, üstlenilen neden, değişen şey, sonraki adım, teşekkür","Düzen: özür, neden, değişiklik, sonraki adım","Dil: sorry that + cümle; sorry for + -ing ya da isim","Üslup: sakin ve insani; \"any inconvenience\" yok, suçlama yok"],"fa":["کامل بودن کار: عذرخواهی دقیق، پذیرفتن علت، آنچه عوض شده، قدم بعدی، تشکر","نظم: عذرخواهی، علت، تغییر، قدم بعدی","زبان: sorry that با جمله؛ sorry for با -ing یا اسم","لحن: آرام و انسانی؛ بدون «any inconvenience» و سرزنش"]}},"speaking":{"id":"mkt-9","course":"marketing","unit":"mkt-9","topic":{"en":"Briefing your manager on a complaint","tr":"Bir şikâyeti yöneticine anlatmak","fa":"گزارش یک شکایت به مدیر"},"warmup":{"en":"Have you seen a company answer a complaint well in public? What did it do?","tr":"Bir şirketin herkese açık bir şikâyete iyi cevap verdiğini gördün mü? Ne yaptı?","fa":"دیده‌ای شرکتی به یک شکایت عمومی خوب جواب بدهد؟ چه کرد؟"},"questions":[{"en":"A 1-star review is spreading. Tell your manager in one minute what happened and why.","tr":"1 yıldızlı bir yorum yayılıyor. Yöneticine bir dakikada ne olduğunu ve nedenini anlat.","fa":"یک نظر یک‌ستاره دارد پخش می‌شود. در یک دقیقه به مدیرت بگو چه شده و چرا."},{"en":"Say what has already been done.","tr":"Şimdiye kadar ne yapıldığını söyle.","fa":"بگو تا حالا چه کاری انجام شده."},{"en":"Your manager asks: \"Can't we just delete it?\" Answer, with a reason.","tr":"Yöneticin soruyor: \"Can't we just delete it?\" Nedeniyle cevap ver.","fa":"مدیرت می‌پرسد: «Can't we just delete it?» با دلیل جواب بده."}],"followups":[{"en":"Now say how you would answer one real complaint about your own work.","tr":"Şimdi kendi işinle ilgili gerçek bir şikâyete nasıl cevap vereceğini söyle.","fa":"حالا بگو به یک شکایت واقعی درباره‌ی کار خودت چطور جواب می‌دهی."}],"expressions":[{"phrase":"What happened is...","meaning":{"en":"Gives the facts first.","tr":"Önce bilgileri verir.","fa":"اول واقعیت‌ها را می‌گوید."}},{"phrase":"It was our mistake, not the customer's.","meaning":{"en":"Owns the problem clearly.","tr":"Sorunu açıkça üstlenir.","fa":"مشکل را روشن می‌پذیرد."}},{"phrase":"We've already...","meaning":{"en":"Shows action.","tr":"Yapılanı gösterir.","fa":"کاری را که انجام شده نشان می‌دهد."}}],"model":"What happened is simple. A customer followed our care label, and the dye ruined her shirts. It was our mistake, not the customer's: the label said 60 degrees, and that dye needs 30. We've already changed the label and emailed her about a replacement. We shouldn't delete the review. Everyone has seen it, so a calm public reply will do more for us.","selfCheck":[{"en":"I gave the facts and the cause.","tr":"Bilgileri ve nedeni söyledim.","fa":"واقعیت‌ها و علت را گفتم."},{"en":"I said what has already been done.","tr":"Şimdiye kadar ne yapıldığını söyledim.","fa":"گفتم تا حالا چه کاری انجام شده."},{"en":"I gave a reason not to delete it.","tr":"Silmemek için bir neden söyledim.","fa":"برای پاک نکردن دلیل آوردم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-9-x","course":"marketing","unit":"mkt-9","type":"exit","items":[{"from":"mkt-9","kind":"blank","prompt":"We're sorry ___ sending you the wrong size.","options":["that","for","of"],"correct":1,"point":2},{"from":"mkt-9","kind":"mcq","prompt":"What comes first in a public reply?","options":["The exact problem, named","A discount code","Your company's history"],"correct":0,"point":1},{"from":"mkt-9","kind":"mcq","prompt":"Why not simply delete a bad review?","options":["Reviews can't be seen by others.","It usually makes the story bigger, and in some places it is illegal.","It has no effect."],"correct":1,"point":1},{"from":"mkt-8","kind":"blank","prompt":"Complaints fell ___ 12 to 3 after we changed the packing.","options":["from","by","at"],"correct":0},{"from":"mkt-6","kind":"mcq","prompt":"You move a LinkedIn post to Instagram. What do you change?","options":["The message","The first line, the length and the next step","The facts"],"correct":1},{"from":"mkt-2","kind":"blank","prompt":"Most ___ the comments under the review were kind.","options":["of","in","from"],"correct":0}]},"explain":{"id":"c-mkt-9-e","course":"marketing","unit":"mkt-9","type":"explain","level":"B1","title":{"en":"When it goes wrong in public","tr":"Herkesin önünde ters gidince","fa":"وقتی کار جلوی چشم همه خراب می‌شود"},"objective":{"en":"After this lesson, you can reply to a public complaint calmly and say what happens next.","tr":"Bu dersin sonunda herkese açık bir şikâyete sakin bir şekilde cevap verebilecek ve sonra ne olacağını söyleyebileceksin.","fa":"بعد از این درس می‌توانی به یک شکایت عمومی آرام جواب بدهی و بگویی قدم بعدی چیست."},"hook":{"en":"You write a public reply to one customer, but everyone who reads it judges you by it. So name the exact problem, accept your part, say what changed and say what happens next.","tr":"Herkese açık cevabı bir müşteriye yazarsın ama onu okuyan herkes seni bu cevapla değerlendirir. Bu yüzden sorunu tam olarak söyle, payına düşeni kabul et, neyin değiştiğini ve sonra ne olacağını yaz.","fa":"جواب عمومی را برای یک مشتری می‌نویسی، ولی هرکس آن را بخواند از روی همان درباره‌ی تو قضاوت می‌کند. پس مشکل را دقیق بگو، سهم خودت را بپذیر، بگو چه چیزی عوض شده و قدم بعدی چیست."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Name it, own it, fix it, next step","tr":"Söyle, üstlen, düzelt, sonraki adım","fa":"مشکل را بگو، بپذیر، درست کن، قدم بعدی را بگو"},"steps":[{"en":"Check the facts, then name the exact problem, so the customer knows you read the complaint.","tr":"Bilgileri kontrol et, sonra sorunu tam olarak söyle ki müşteri şikâyetini okuduğunu anlasın.","fa":"واقعیت‌ها را بررسی کن و بعد مشکل را دقیق بگو تا مشتری بفهمد شکایتش را خوانده‌ای.","ex":"We're sorry that your parcel arrived broken."},{"en":"Own what is yours: say it was your fault. Blame and \"any inconvenience\" sound careless.","tr":"Sana ait olanı üstlen: hatanın senin olduğunu söyle. Suçlama ve \"any inconvenience\" umursamaz duyulur.","fa":"چیزی را که تقصیر توست بپذیر و این را بگو. سرزنش و «any inconvenience» نشان می‌دهند برایت مهم نیست.","ex":"Our packing was too thin for this mug."},{"en":"Say what you have already changed. Action convinces readers more than a promise.","tr":"Şimdiden neyi değiştirdiğini söyle. Yapılmış iş okuru sözden daha çok ikna eder.","fa":"بگو تا حالا چه چیزی را عوض کرده‌ای. کار انجام‌شده مخاطب را بیشتر از قول قانع می‌کند.","ex":"We now use double boxes for every order."},{"en":"Give the next step. Move private details to a private message, to protect the customer.","tr":"Sonraki adımı söyle. Müşteriyi korumak için özel bilgileri özel mesaja taşı.","fa":"قدم بعدی را بگو و برای حفظ حریم مشتری، جزئیات خصوصی را به پیام خصوصی ببر.","ex":"We've emailed you about a replacement."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"An exact apology: sorry that, sorry for, apologise for","tr":"Net bir özür: sorry that, sorry for, apologise for","fa":"عذرخواهی دقیق: sorry that، sorry for، apologise for"},"steps":[{"en":"sorry that + a full sentence.","tr":"sorry that + tam bir cümle.","fa":"بعد از sorry that یک جمله‌ی کامل می‌آید.","ex":"We're sorry that our label was wrong."},{"en":"sorry for + -ing or a noun.","tr":"sorry for + -ing ya da bir isim.","fa":"بعد از sorry for فعل -ing‌دار یا یک اسم می‌آید.","ex":"sorry for damaging your shirts"},{"en":"apologise for the thing, to the person.","tr":"Olan şey için for, kişi için to.","fa":"بعد از apologise، برای آن اتفاق for می‌آید و برای آن شخص to.","ex":"We apologise to the customer for the mistake."},{"en":"Then say what you have done.","tr":"Sonra ne yaptığını söyle.","fa":"بعد بگو چه کرده‌ای.","ex":"We've changed the label."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["sorry that + full sentence","We're sorry that our towel damaged your shirts."],["sorry for + -ing","We're sorry for damaging your shirts."],["sorry for + noun","We're sorry for the trouble."],["apologise to + person + for + noun / -ing","We apologise to the customer for the mistake."]]},"tip":{"en":"Turkish says \"zarar verdiğimiz için özür dileriz\" and Persian «بابت آسیبی که زدیم عذر می‌خواهیم»: one form carries the reason. English needs for + -ing or that + a full sentence, so learners write \"sorry for damage\".","tr":"Türkçede \"zarar verdiğimiz için özür dileriz\" deriz; sebep tek bir yapının içindedir. İngilizcede for + -ing ya da that + tam cümle gerekir; bu yüzden \"sorry for damage\" yazılır.","fa":"در فارسی می‌گوییم «بابت آسیبی که زدیم عذر می‌خواهیم» و دلیل در یک ساختار می‌آید. انگلیسی for با -ing یا that با جمله‌ی کامل لازم دارد؛ برای همین می‌نویسیم «sorry for damage»."},"wrong":"We are sorry for your towel arrived late.","right":"We are sorry that your towel arrived late."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Don't delete bad reviews","tr":"Kötü yorumları silme","fa":"نظرهای منفی را پاک نکن"},"body":{"en":"In the UK, since April 2025, consumer law bans fake reviews and misleading review information, such as hiding negative reviews. Even where it is legal, deleting criticism usually brings more attention to it. Check local rules, and update the thread once it is solved.","tr":"Birleşik Krallık'ta Nisan 2025'ten beri tüketici hukuku sahte yorumları ve olumsuz yorumları gizlemek gibi yanıltıcı uygulamaları yasaklıyor. Yasal olduğu yerde bile eleştiriyi silmek çoğu zaman ona daha çok dikkat çeker. Yerel kuralları kontrol et, sorun çözülünce de yorumun altına bilgi ver.","fa":"در بریتانیا از آوریل ۲۰۲۵ قانون، نظرهای جعلی و اطلاعات گمراه‌کننده مثل پنهان کردن نظرهای منفی را ممنوع کرده است. حتی جایی که قانونی است، پاک کردن انتقاد معمولاً توجه بیشتری به آن جلب می‌کند. قوانین محلی را بررسی کن و وقتی مشکل حل شد، زیر همان نظر خبر بده."},"phrases":[{"phrase":"What happened is...","meaning":{"en":"Gives the facts first.","tr":"Önce bilgileri verir.","fa":"اول واقعیت‌ها را می‌گوید."}},{"phrase":"It was our mistake, not the customer's.","meaning":{"en":"Owns the problem clearly.","tr":"Sorunu açıkça üstlenir.","fa":"مشکل را روشن می‌پذیرد."}},{"phrase":"We've already...","meaning":{"en":"Shows action.","tr":"Yapılanı gösterir.","fa":"کاری را که انجام شده نشان می‌دهد."}},{"phrase":"take responsibility","meaning":{"en":"To say that a mistake was yours.","tr":"sorumluluğu üstlenmek","fa":"مسئولیت را پذیرفتن"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Rewrite a reply that ends the conversation","tr":"Konuşmayı bitiren bir cevabı yeniden yaz","fa":"جوابی را که گفت‌وگو را تمام می‌کند بازنویسی کن"},"item":"We apologise for any inconvenience. Our products are of the highest quality. Please contact customer service. Facts: her mug arrived broken; the packing was too thin; we now use double boxes; we emailed her about a replacement.","answer":"We're sorry that your mug arrived broken. Our packing was too thin, and we now use double boxes. We've emailed you about a replacement.","walk":[{"en":"Replace \"any inconvenience\" with the real problem.","tr":"\"Any inconvenience\" yerine gerçek sorunu yaz.","fa":"به‌جای «any inconvenience» مشکل واقعی را بنویس."},{"en":"Delete the line that argues: \"highest quality\". It tells her she is wrong.","tr":"Tartışan satırı sil: \"highest quality\". Bu satır ona haksız olduğunu söyler.","fa":"جمله‌ی «highest quality» را حذف کن، چون با مشتری بحث می‌کند و به او می‌گوید اشتباه می‌کند."},{"en":"Do the work yourself: say what you changed and what you sent.","tr":"İşi müşteriye bırakma: neyi değiştirdiğini ve ne gönderdiğini söyle.","fa":"کار را گردن مشتری نینداز: بگو چه چیزی را عوض کردی و چه فرستادی."}]},"quick":{"prompt":"A public reply is also written for ___ customers.","options":["future","former","fake"],"correct":0,"why":{"en":"future: people who read it later judge how you behave when something goes wrong.","tr":"future: sonradan okuyanlar, işler ters gidince nasıl davrandığını değerlendirir.","fa":"جواب future است: کسانی که بعداً می‌خوانند می‌سنجند وقتی کاری خراب می‌شود چه رفتاری داری."}},"remember":{"en":"Name it, own it, say what changed, say what happens next. You can now answer a public complaint calmly, in four short moves.","tr":"Sorunu söyle, üstlen, neyin değiştiğini ve sonra ne olacağını söyle. Artık herkese açık bir şikâyete dört kısa adımda sakince cevap verebilirsin.","fa":"مشکل را بگو، بپذیر، بگو چه چیزی عوض شده و قدم بعدی چیست. حالا می‌توانی در چهار قدم کوتاه به یک شکایت عمومی آرام جواب بدهی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Owning a past mistake: should have, shouldn't have","tr":"Geçmişteki bir hatayı üstlenmek: should have, shouldn't have","fa":"پذیرفتن اشتباه گذشته: should have، shouldn't have"},"steps":[{"en":"Right thing that did not happen: should have + past participle.","tr":"Olması gerekip olmayan şey: should have + üçüncü hâl.","fa":"should have با اسم مفعول همان «باید ... می‌کردیم» فارسی است: کاری که باید انجام می‌دادی و ندادی.","ex":"The label should have said 30°C."},{"en":"Wrong thing that happened: shouldn't have + past participle.","tr":"Olmaması gerekip olan şey: shouldn't have + üçüncü hâl.","fa":"shouldn't have با اسم مفعول یعنی کاری که نباید می‌کردی و کردی.","ex":"We shouldn't have used one label."},{"en":"Say we, not you: own it.","tr":"You değil, we de: hatayı üstlen.","fa":"بگو we، نه you: اشتباه را بپذیر.","ex":"We should have checked."}],"table":{"headers":{"en":["Form","Use","Example"],"tr":["Yapı","Kullanım","Örnek"],"fa":["ساختار","کاربرد","مثال"]},"rows":[["should have + past participle","the right thing did not happen","Our label should have said 30°C."],["shouldn't have + past participle","the wrong thing happened","We shouldn't have used one label for every colour."]]},"body":{"en":"B2: in your public reply, own the mistake with should have or shouldn't have + past participle.","tr":"B2: herkese açık yanıtında hatayı should have ya da shouldn't have + üçüncü hâl ile üstlen.","fa":"B2: در جواب عمومی‌ات اشتباه را با should have یا shouldn't have و اسم مفعول بپذیر."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
